def gen_html_file(tdm_ch, claims: ClaimCollection):
    """Generate mpplain_multimark.html in the given output directory."""
    cbody = build_body(claims=claims)
    return author.help_gen_html_file(__file__, tdm_ch, _FNAME, _TITLE, cbody)


def build_body(*, claims: ClaimCollection):
    jer_rows = cmn.emit_claim_by_id(
        claims=claims,
        claim_id="mp.plain.templates.jerusalem.set",
    )
    multimark_rows = [
        *cmn.accent_rows_for_templates(_MULTIMARK_TEMPLATES[:2]),
        *cmn.other_rows_for_templates(_MULTIMARK_TEMPLATES[2:]),
        *jer_rows,
    ]
    plain_back_link = author.anchor_h("Reading $MAM-parsed-plain", _PLAIN_DOC)
    return [
        author.heading_level_1("Multimark templates"),
        author.para(["← Back to ", plain_back_link]),
        author.para(
            "These templates mark characters that carry multiple marks"
            " and related Jerusalem-form notes."
        ),
        tblh.tmpl_purp_table(multimark_rows),
    ]


def _build_body(*, claims: ClaimCollection):
    return build_body(claims=claims)
